```json
{
  "title": "Đà Lạt một góc, trọn một ngày",
  "summary": "Một ngày chậm rãi quanh khu trung tâm, cà phê sáng, món ngon trưa chiều và quán nhỏ ấm cúng sau khi trời tối.",
  "stops": [
    {
      "poi_id": "p14",
      "kind": "activity",
      "must_do_id": null,
      "note": "Đi bộ nhẹ nhàng ở quảng trường cho tỉnh ngủ, ngắm nhịp sống Đà Lạt buổi sáng."
    },
    {
      "poi_id": "p179",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa trưa gọn mà đậm vị phố, bánh căn nóng hổi ngay trong khu này."
    },
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": null,
      "note": "Ghé nhà thờ Con Gà ngắm kiến trúc xưa, chỗ này gần và hợp buổi sáng."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối đến ngồi xuống ăn nem nướng thong thả, ngon quá (so tasty) là vừa."
    },
    {
      "poi_id": "p52",
      "kind": "activity",
      "must_do_id": null,
      "note": "Sau bữa tối ghé Lululola nhâm nhi cà phê, hợp với cú đêm và không phải đi xa."
    }
  ]
}
```

